import 'package:flutter/material.dart';

Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();
  runApp(const MaterialApp(home: Scaffold(body: Center(child: Text('Fleet Console')))));
}

/// Injectable clock so tests can freeze "now" for stale/offline rules.
abstract class AppClock {
  DateTime now();
}

class SystemClock implements AppClock {
  const SystemClock();

  @override
  DateTime now() => DateTime.now().toUtc();
}

class FakeClock implements AppClock {
  FakeClock(DateTime now) : _now = now.toUtc();

  DateTime _now;

  @override
  DateTime now() => _now;

  void setNow(DateTime value) => _now = value.toUtc();

  void advance(Duration d) => _now = _now.add(d);
}

/// Operator-facing thresholds from the assignment, in one place.
abstract final class FleetRules {
  static const staleAfter = Duration(minutes: 10);
  static const lowBatteryPct = 20.0;
  static const criticalBatteryPct = 10.0;
  static const overheatC = 45.0;
  static const undoWindow = Duration(seconds: 5);

  static const gpsAccuracyMaxM = 50.0;
  static const geofenceHysteresisM = 25.0;
  static const dwellSamples = 3;
  static const dwellDuration = Duration(seconds: 60);
  static const locationGapBreak = Duration(minutes: 10);

  static const retentionRaw = Duration(days: 7);

  static const signalSoc = 'soc';
  static const signalRange = 'range';
  static const signalSpeed = 'speed';
  static const signalBatteryTemp = 'battery_temp';
  static const signalOdometer = 'odometer';
  static const signalIgnition = 'ignition';
  static const signalLat = 'lat';
  static const signalLon = 'lon';
  static const signalGpsAccuracy = 'gps_accuracy';

  static const alertSoc = 'battery_soc';
  static const alertTemp = 'battery_temp';

  static const registerSignals = <String>[
    signalSoc,
    signalRange,
    signalSpeed,
    signalBatteryTemp,
    signalOdometer,
  ];
}

import 'dart:math' as math;

/// Haversine distance in metres. Inputs are WGS84 degrees.
double haversineMeters({
  required double lat1,
  required double lon1,
  required double lat2,
  required double lon2,
}) {
  const earthRadiusM = 6371000.0;
  final dLat = _rad(lat2 - lat1);
  final dLon = _rad(lon2 - lon1);
  final a = math.sin(dLat / 2) * math.sin(dLat / 2) +
      math.cos(_rad(lat1)) *
          math.cos(_rad(lat2)) *
          math.sin(dLon / 2) *
          math.sin(dLon / 2);
  return 2 * earthRadiusM * math.asin(math.min(1, math.sqrt(a)));
}

double _rad(double deg) => deg * math.pi / 180.0;

/// Linear interpolate along a great-circle-ish planar shortcut for the demo
/// simulator (short hops between nearby depots).
({double lat, double lon}) lerpLatLon(
  double lat1,
  double lon1,
  double lat2,
  double lon2,
  double t,
) {
  final clamped = t.clamp(0.0, 1.0);
  return (
    lat: lat1 + (lat2 - lat1) * clamped,
    lon: lon1 + (lon2 - lon1) * clamped,
  );
}

enum VehicleStatus { offline, moving, idle, stopped }

enum AlertSeverity { warning, critical }

enum SignalVerdict { normal, alert, stale }

enum TripStatus { inProgress, completed }

enum FleetFilter { all, moving, idle, stopped, offline }

class VehicleRow {
  const VehicleRow({
    required this.id,
    required this.regNumber,
    required this.model,
    required this.status,
    this.soc,
    this.rangeKm,
    this.speed,
    this.ignitionOn,
    this.lastPing,
    this.currentGeofenceId,
    this.currentGeofenceName,
    this.openAlertCount = 0,
    this.hasCriticalAlert = false,
  });

  final String id;
  final String regNumber;
  final String model;
  final VehicleStatus status;
  final double? soc;
  final double? rangeKm;
  final double? speed;
  final bool? ignitionOn;
  final DateTime? lastPing;
  final String? currentGeofenceId;
  final String? currentGeofenceName;
  final int openAlertCount;
  final bool hasCriticalAlert;
}

class SignalReading {
  const SignalReading({
    required this.signal,
    required this.label,
    required this.unit,
    this.value,
    this.eventTime,
    this.verdict,
  });

  final String signal;
  final String label;
  final String unit;
  final double? value;
  final DateTime? eventTime;
  final SignalVerdict? verdict;
}

class VehicleAlert {
  const VehicleAlert({
    required this.id,
    required this.vehicleId,
    required this.kind,
    required this.severity,
    required this.openedAt,
    this.resolvedAt,
    this.dismissedAt,
    this.dismissReason,
  });

  final String id;
  final String vehicleId;
  final String kind;
  final AlertSeverity severity;
  final DateTime openedAt;
  final DateTime? resolvedAt;
  final DateTime? dismissedAt;
  final String? dismissReason;

  bool get isOpen => resolvedAt == null && dismissedAt == null;

  String get title => switch (kind) {
        'battery_soc' => severity == AlertSeverity.critical
            ? 'Battery critically low'
            : 'Low battery',
        'battery_temp' => 'Battery overheating',
        _ => kind,
      };
}

class Geofence {
  const Geofence({
    required this.id,
    required this.name,
    required this.lat,
    required this.lon,
    required this.radiusM,
    required this.active,
    required this.version,
    required this.createdAt,
    required this.updatedAt,
    this.deactivatedAt,
    this.vehicleCount = 0,
  });

  final String id;
  final String name;
  final double lat;
  final double lon;
  final double radiusM;
  final bool active;
  final int version;
  final DateTime createdAt;
  final DateTime updatedAt;
  final DateTime? deactivatedAt;
  final int vehicleCount;
}

class Trip {
  const Trip({
    required this.id,
    required this.vehicleId,
    required this.originGeofenceId,
    required this.startedAt,
    required this.status,
    this.originName,
    this.destGeofenceId,
    this.destName,
    this.endedAt,
  });

  final String id;
  final String vehicleId;
  final String originGeofenceId;
  final String? originName;
  final String? destGeofenceId;
  final String? destName;
  final DateTime startedAt;
  final DateTime? endedAt;
  final TripStatus status;
}

class SocPoint {
  const SocPoint(this.time, this.soc);
  final DateTime time;
  final double soc;
}

class FilterCounts {
  const FilterCounts({
    required this.all,
    required this.moving,
    required this.idle,
    required this.stopped,
    required this.offline,
  });

  final int all;
  final int moving;
  final int idle;
  final int stopped;
  final int offline;

  int forFilter(FleetFilter filter) => switch (filter) {
        FleetFilter.all => all,
        FleetFilter.moving => moving,
        FleetFilter.idle => idle,
        FleetFilter.stopped => stopped,
        FleetFilter.offline => offline,
      };
}

class FleetSnapshot {
  const FleetSnapshot({
    required this.vehicles,
    required this.counts,
    required this.asOf,
    required this.queryMicros,
  });

  final List<VehicleRow> vehicles;
  final FilterCounts counts;
  final DateTime asOf;
  final int queryMicros;
}

class TelemetryPacket {
  const TelemetryPacket({
    required this.id,
    required this.vehicleId,
    required this.eventTime,
    required this.signals,
  });

  final String id;
  final String vehicleId;
  final DateTime eventTime;

  /// Sparse map: a packet may carry only a subset of signals.
  final Map<String, double> signals;
}

class LocationSample {
  const LocationSample({
    required this.packetId,
    required this.eventTime,
    required this.lat,
    required this.lon,
    this.accuracyM,
  });

  final String packetId;
  final DateTime eventTime;
  final double lat;
  final double lon;
  final double? accuracyM;
}

class FenceVersion {
  const FenceVersion({
    required this.geofenceId,
    required this.version,
    required this.name,
    required this.lat,
    required this.lon,
    required this.radiusM,
    required this.validFrom,
    this.validTo,
  });

  final String geofenceId;
  final int version;
  final String name;
  final double lat;
  final double lon;
  final double radiusM;
  final DateTime validFrom;
  final DateTime? validTo;

  bool validAt(DateTime t) {
    if (t.isBefore(validFrom)) return false;
    if (validTo == null) return true;
    return t.isBefore(validTo!);
  }
}

class ConfirmedTransition {
  const ConfirmedTransition({
    required this.id,
    required this.vehicleId,
    required this.geofenceId,
    required this.geofenceVersion,
    required this.kind,
    required this.eventTime,
    this.packetId,
  });

  final String id;
  final String vehicleId;
  final String geofenceId;
  final int geofenceVersion;

  /// `confirmed_enter` or `confirmed_exit`
  final String kind;
  final DateTime eventTime;
  final String? packetId;
}

class ReplayResult {
  const ReplayResult({
    required this.events,
    required this.trips,
    this.currentGeofenceId,
  });

  final List<ConfirmedTransition> events;
  final List<Trip> trips;
  final String? currentGeofenceId;
}

class IngestResult {
  const IngestResult({
    required this.accepted,
    required this.duplicate,
  });

  final bool accepted;
  final bool duplicate;

  static const skippedDuplicate = IngestResult(accepted: false, duplicate: true);
  static const stored = IngestResult(accepted: true, duplicate: false);
}

import 'package:dart_duckdb/dart_duckdb.dart';

import 'schema.dart';

/// File-backed (or test) DuckDB connection. UI and engines read through this.
class FleetDatabase {
  FleetDatabase._(this.path, this._database, this._connection);

  final String path;
  final Database _database;
  final Connection _connection;
  bool _closed = false;

  Connection get connection => _connection;

  static Future<FleetDatabase> open(String path) async {
    final database = await duckdb.open(path);
    final connection = await duckdb.connect(database);
    final db = FleetDatabase._(path, database, connection);
    await db._migrate();
    return db;
  }

  Future<void> _migrate() async {
    for (final stmt in fleetSchemaSql
        .split(';')
        .map((s) => s.trim())
        .where((s) => s.isNotEmpty)) {
      await _connection.execute('$stmt;');
    }
  }

  Future<void> execute(String sql, [List<Object?> params = const []]) async {
    if (params.isEmpty) {
      await _connection.execute(sql);
      return;
    }
    final stmt = await _connection.prepare(sql);
    try {
      stmt.bindParams(params);
      await stmt.execute();
    } finally {
      await stmt.dispose();
    }
  }

  Future<List<Map<String, Object?>>> select(
    String sql, [
    List<Object?> params = const [],
  ]) async {
    late final ResultSet rs;
    PreparedStatement? stmt;
    if (params.isEmpty) {
      rs = await _connection.query(sql);
    } else {
      stmt = await _connection.prepare(sql);
      stmt.bindParams(params);
      rs = await stmt.execute();
    }
    try {
      final names = rs.columnNames;
      return [
        for (final row in rs.fetchAll())
          {for (var i = 0; i < names.length; i++) names[i]: row[i]},
      ];
    } finally {
      await rs.dispose();
      await stmt?.dispose();
    }
  }

  Future<Map<String, Object?>?> selectOne(
    String sql, [
    List<Object?> params = const [],
  ]) async {
    final rows = await select(sql, params);
    if (rows.isEmpty) return null;
    return rows.first;
  }

  Future<void> transaction(Future<void> Function() body) async {
    await _connection.execute('BEGIN');
    try {
      await body();
      await _connection.execute('COMMIT');
    } catch (e) {
      try {
        await _connection.execute('ROLLBACK');
      } catch (_) {}
      rethrow;
    }
  }

  Future<Appender> appender(String table) => _connection.append(table, null);

  Future<void> close() async {
    if (_closed) return;
    _closed = true;
    await _connection.dispose();
    await _database.dispose();
  }
}

import '../core/constants.dart';
import '../core/geo.dart';
import '../domain/models.dart';

/// Confirmed geofence enter/exit from event-time location history.
///
/// Strategy (see docs/DECISIONS.md):
/// duplicates are gone before we get here; we walk event_time order;
/// drop inaccurate GPS; hysteresis + dwell; gaps break membership;
/// innermost fence wins overlaps; trips are derived from confirmed transitions.
class GeofenceReplay {
  ReplayResult replay({
    required String vehicleId,
    required List<LocationSample> points,
    required List<FenceVersion> fences,
  }) {
    final ordered = [...points]..sort((a, b) => a.eventTime.compareTo(b.eventTime));
    final usable = <LocationSample>[];
    LocationSample? prevKept;
    for (final p in ordered) {
      if (p.accuracyM != null && p.accuracyM! > FleetRules.gpsAccuracyMaxM) {
        continue;
      }
      if (prevKept != null && p.eventTime.isAtSameMomentAs(prevKept.eventTime)) {
        continue;
      }
      usable.add(p);
      prevKept = p;
    }

    String? candidateId;
    int dwellCount = 0;
    DateTime? dwellStart;
    String? confirmedId;
    final events = <ConfirmedTransition>[];
    LocationSample? prev;

    void resetDwell(String? next, DateTime at) {
      candidateId = next;
      dwellCount = next == null && confirmedId == null ? 0 : 1;
      dwellStart = at;
    }

    for (final point in usable) {
      if (prev != null &&
          point.eventTime.difference(prev.eventTime) > FleetRules.locationGapBreak) {
        candidateId = null;
        dwellCount = 0;
        dwellStart = null;
      }

      final next = _candidateFence(point, fences, confirmedId);
      if (next == candidateId) {
        dwellCount += 1;
        dwellStart ??= point.eventTime;
      } else {
        resetDwell(next, point.eventTime);
      }

      final dwellTime = dwellStart == null
          ? Duration.zero
          : point.eventTime.difference(dwellStart!);
      final confirmed = dwellCount >= FleetRules.dwellSamples ||
          dwellTime >= FleetRules.dwellDuration;

      if (confirmed && next != confirmedId) {
        if (confirmedId != null) {
          final fence = _fenceAt(confirmedId, point.eventTime, fences);
          events.add(
            ConfirmedTransition(
              id: _eventId(vehicleId, 'confirmed_exit', confirmedId, point.eventTime),
              vehicleId: vehicleId,
              geofenceId: confirmedId,
              geofenceVersion: fence?.version ?? 0,
              kind: 'confirmed_exit',
              eventTime: point.eventTime,
              packetId: point.packetId,
            ),
          );
        }
        if (next != null) {
          final fence = _fenceAt(next, point.eventTime, fences)!;
          events.add(
            ConfirmedTransition(
              id: _eventId(vehicleId, 'confirmed_enter', next, point.eventTime),
              vehicleId: vehicleId,
              geofenceId: next,
              geofenceVersion: fence.version,
              kind: 'confirmed_enter',
              eventTime: point.eventTime,
              packetId: point.packetId,
            ),
          );
        }
        confirmedId = next;
        dwellCount = 0;
        dwellStart = point.eventTime;
      }

      prev = point;
    }

    final trips = deriveTrips(vehicleId: vehicleId, events: events);
    return ReplayResult(
      events: events,
      trips: trips,
      currentGeofenceId: confirmedId,
    );
  }

  List<Trip> deriveTrips({
    required String vehicleId,
    required List<ConfirmedTransition> events,
  }) {
    final ordered = [...events]..sort((a, b) => a.eventTime.compareTo(b.eventTime));
    final trips = <Trip>[];
    Trip? active;

    for (final event in ordered) {
      if (event.kind == 'confirmed_exit') {
        active ??= Trip(
          id: _tripId(vehicleId, event.geofenceId, event.eventTime),
          vehicleId: vehicleId,
          originGeofenceId: event.geofenceId,
          startedAt: event.eventTime,
          status: TripStatus.inProgress,
        );
      } else if (event.kind == 'confirmed_enter' && active != null) {
        trips.add(
          Trip(
            id: active.id,
            vehicleId: vehicleId,
            originGeofenceId: active.originGeofenceId,
            destGeofenceId: event.geofenceId,
            startedAt: active.startedAt,
            endedAt: event.eventTime,
            status: TripStatus.completed,
          ),
        );
        active = null;
      }
    }
    if (active != null) trips.add(active);
    return trips;
  }

  String? _candidateFence(
    LocationSample point,
    List<FenceVersion> fences,
    String? confirmedId,
  ) {
    final valid = fences.where((f) => f.validAt(point.eventTime)).toList();
    final inside = <FenceVersion>[];
    for (final fence in valid) {
      final dist = haversineMeters(
        lat1: point.lat,
        lon1: point.lon,
        lat2: fence.lat,
        lon2: fence.lon,
      );
      if (dist <= fence.radiusM - FleetRules.geofenceHysteresisM) {
        inside.add(fence);
      }
    }
    if (inside.isNotEmpty) {
      inside.sort((a, b) {
        final r = a.radiusM.compareTo(b.radiusM);
        if (r != 0) return r;
        return a.geofenceId.compareTo(b.geofenceId);
      });
      return inside.first.geofenceId;
    }

    if (confirmedId != null) {
      final current = valid.where((f) => f.geofenceId == confirmedId);
      if (current.isNotEmpty) {
        final fence = current.first;
        final dist = haversineMeters(
          lat1: point.lat,
          lon1: point.lon,
          lat2: fence.lat,
          lon2: fence.lon,
        );
        if (dist < fence.radiusM + FleetRules.geofenceHysteresisM) {
          return confirmedId;
        }
      }
    }
    return null;
  }

  FenceVersion? _fenceAt(
    String id,
    DateTime at,
    List<FenceVersion> fences,
  ) {
    final matches = fences.where((f) => f.geofenceId == id && f.validAt(at));
    if (matches.isEmpty) return null;
    return matches.first;
  }

  String _eventId(String vehicleId, String kind, String fenceId, DateTime t) =>
      'evt_${vehicleId}_${kind}_${fenceId}_${t.microsecondsSinceEpoch}';

  String _tripId(String vehicleId, String originId, DateTime startedAt) =>
      'trip_${vehicleId}_${originId}_${startedAt.microsecondsSinceEpoch}';
}

import '../../core/constants.dart';
import '../../domain/models.dart';

class AlertEvaluation {
  const AlertEvaluation({
    required this.kind,
    this.severity,
    required this.inBreach,
    required this.fresh,
  });

  final String kind;
  final AlertSeverity? severity;
  final bool inBreach;
  final bool fresh;
}

/// Fresh-only thresholds. SOC is one escalating alert, not two rows.
class AlertRules {
  static List<AlertEvaluation> evaluate({
    required DateTime now,
    required Map<String, ({double value, DateTime eventTime})> latest,
  }) {
    return [
      _soc(now, latest[FleetRules.signalSoc]),
      _temp(now, latest[FleetRules.signalBatteryTemp]),
    ];
  }

  static AlertEvaluation _soc(
    DateTime now,
    ({double value, DateTime eventTime})? reading,
  ) {
    if (reading == null) {
      return const AlertEvaluation(
        kind: FleetRules.alertSoc,
        inBreach: false,
        fresh: false,
      );
    }
    final fresh = now.difference(reading.eventTime) <= FleetRules.staleAfter;
    if (!fresh) {
      return const AlertEvaluation(
        kind: FleetRules.alertSoc,
        inBreach: false,
        fresh: false,
      );
    }
    if (reading.value < FleetRules.criticalBatteryPct) {
      return const AlertEvaluation(
        kind: FleetRules.alertSoc,
        severity: AlertSeverity.critical,
        inBreach: true,
        fresh: true,
      );
    }
    if (reading.value < FleetRules.lowBatteryPct) {
      return const AlertEvaluation(
        kind: FleetRules.alertSoc,
        severity: AlertSeverity.warning,
        inBreach: true,
        fresh: true,
      );
    }
    return const AlertEvaluation(
      kind: FleetRules.alertSoc,
      inBreach: false,
      fresh: true,
    );
  }

  static AlertEvaluation _temp(
    DateTime now,
    ({double value, DateTime eventTime})? reading,
  ) {
    if (reading == null) {
      return const AlertEvaluation(
        kind: FleetRules.alertTemp,
        inBreach: false,
        fresh: false,
      );
    }
    final fresh = now.difference(reading.eventTime) <= FleetRules.staleAfter;
    if (!fresh) {
      return const AlertEvaluation(
        kind: FleetRules.alertTemp,
        inBreach: false,
        fresh: false,
      );
    }
    if (reading.value > FleetRules.overheatC) {
      return const AlertEvaluation(
        kind: FleetRules.alertTemp,
        severity: AlertSeverity.critical,
        inBreach: true,
        fresh: true,
      );
    }
    return const AlertEvaluation(
      kind: FleetRules.alertTemp,
      inBreach: false,
      fresh: true,
    );
  }
}

SignalVerdict? verdictFor({
  required DateTime now,
  required String signal,
  required double value,
  required DateTime eventTime,
}) {
  if (now.difference(eventTime) > FleetRules.staleAfter) {
    return SignalVerdict.stale;
  }
  if (signal == FleetRules.signalSoc && value < FleetRules.lowBatteryPct) {
    return SignalVerdict.alert;
  }
  if (signal == FleetRules.signalBatteryTemp && value > FleetRules.overheatC) {
    return SignalVerdict.alert;
  }
  return SignalVerdict.normal;
}

DateTime? asDateTime(Object? value) {
  if (value == null) return null;
  if (value is DateTime) return value.toUtc();
  if (value is String) return DateTime.parse(value).toUtc();
  return null;
}

DateTime requireDateTime(Object? value) => asDateTime(value)!;

double? asDouble(Object? value) {
  if (value == null) return null;
  if (value is double) return value;
  if (value is int) return value.toDouble();
  if (value is num) return value.toDouble();
  if (value is String) return double.tryParse(value);
  return null;
}

int asInt(Object? value, [int fallback = 0]) {
  if (value == null) return fallback;
  if (value is int) return value;
  if (value is BigInt) return value.toInt();
  if (value is num) return value.toInt();
  if (value is String) return int.tryParse(value) ?? fallback;
  return fallback;
}

bool asBool(Object? value) {
  if (value == null) return false;
  if (value is bool) return value;
  if (value is num) return value != 0;
  if (value is String) return value == 'true' || value == '1';
  return false;
}

String? asString(Object? value) => value?.toString();

import '../core/clock.dart';
import '../core/constants.dart';
import '../domain/models.dart';
import 'duckdb/coerce.dart';
import 'duckdb/fleet_database.dart';
import 'duckdb/schema.dart';
import 'engines/alert_engine.dart';
import 'engines/geofence_engine.dart';

/// All operator reads go through SQL on [FleetDatabase]. This class is the
/// write path (ingest, dismiss, geofence CRUD) plus query helpers.
class FleetRepository {
  FleetRepository(this.db, {AppClock clock = const SystemClock()})
      : _clock = clock,
        _replay = GeofenceReplay();

  final FleetDatabase db;
  final AppClock _clock;
  final GeofenceReplay _replay;

  DateTime get now => _clock.now();

  Future<void> upsertVehicle({
    required String id,
    required String regNumber,
    required String model,
  }) {
    return db.execute(
      '''
      INSERT INTO vehicles (id, reg_number, model) VALUES (?, ?, ?)
      ON CONFLICT (id) DO UPDATE SET
        reg_number = excluded.reg_number,
        model = excluded.model
      ''',
      [id, regNumber, model],
    );
  }

  Future<IngestResult> ingestPacket(
    TelemetryPacket packet, {
    bool replayLocation = true,
    bool recomputeAlerts = true,
  }) async {
    final eventTime = packet.eventTime.toUtc();
    final ingestTime = now;

    final existing = await db.selectOne(
      'SELECT id FROM packets WHERE vehicle_id = ? AND event_time = ?',
      [packet.vehicleId, eventTime],
    );
    if (existing != null) return IngestResult.skippedDuplicate;

    await db.transaction(() async {
      await db.execute(
        'INSERT INTO packets (id, vehicle_id, event_time, ingest_time) VALUES (?, ?, ?, ?)',
        [packet.id, packet.vehicleId, eventTime, ingestTime],
      );
      for (final entry in packet.signals.entries) {
        await db.execute(
          '''
          INSERT INTO readings (packet_id, vehicle_id, signal, value, event_time)
          VALUES (?, ?, ?, ?, ?)
          ''',
          [packet.id, packet.vehicleId, entry.key, entry.value, eventTime],
        );
        await db.execute(
          '''
          INSERT INTO vehicle_signal_latest (vehicle_id, signal, value, event_time, packet_id)
          VALUES (?, ?, ?, ?, ?)
          ON CONFLICT (vehicle_id, signal) DO UPDATE SET
            value = excluded.value,
            event_time = excluded.event_time,
            packet_id = excluded.packet_id
          WHERE excluded.event_time >= vehicle_signal_latest.event_time
          ''',
          [packet.vehicleId, entry.key, entry.value, eventTime, packet.id],
        );
      }
    });

    if (replayLocation &&
        packet.signals.containsKey(FleetRules.signalLat) &&
        packet.signals.containsKey(FleetRules.signalLon)) {
      await replayVehicle(packet.vehicleId);
    }
    if (recomputeAlerts) {
      await recomputeAlertsFor(packet.vehicleId);
    }
    return IngestResult.stored;
  }

  /// Bulk append used by the 2M-row backfill. Caller rebuilds latest + replay.
  Future<int> appendPackets(List<TelemetryPacket> batch) async {
    if (batch.isEmpty) return 0;
    var stored = 0;
    final packetApp = await db.appender('packets');
    final readingApp = await db.appender('readings');
    try {
      final ingestTime = now;
      for (final packet in batch) {
        final eventTime = packet.eventTime.toUtc();
        packetApp.append(packet.id);
        packetApp.append(packet.vehicleId);
        packetApp.append(eventTime);
        packetApp.append(ingestTime);
        packetApp.endRow();
        for (final entry in packet.signals.entries) {
          readingApp.append(packet.id);
          readingApp.append(packet.vehicleId);
          readingApp.append(entry.key);
          readingApp.append(entry.value);
          readingApp.append(eventTime);
          readingApp.endRow();
        }
        stored += packet.signals.length;
      }
      packetApp.flush();
      readingApp.flush();
    } finally {
      packetApp.dispose();
      readingApp.dispose();
    }
    return stored;
  }

  Future<void> rebuildLatestFromLog() async {
    await db.execute('DELETE FROM vehicle_signal_latest');
    await db.execute('''
      INSERT INTO vehicle_signal_latest (vehicle_id, signal, value, event_time, packet_id)
      SELECT vehicle_id, signal, value, event_time, packet_id
      FROM (
        SELECT *, ROW_NUMBER() OVER (
          PARTITION BY vehicle_id, signal ORDER BY event_time DESC
        ) AS rn
        FROM readings
      )
      WHERE rn = 1
    ''');
  }

  Future<void> replayVehicle(String vehicleId) async {
    final pointRows = await db.select(
      '''
      SELECT p.id AS packet_id, p.event_time,
             lat.value AS lat, lon.value AS lon, acc.value AS gps_accuracy
      FROM packets p
      JOIN readings lat ON lat.packet_id = p.id AND lat.signal = 'lat'
      JOIN readings lon ON lon.packet_id = p.id AND lon.signal = 'lon'
      LEFT JOIN readings acc ON acc.packet_id = p.id AND acc.signal = 'gps_accuracy'
      WHERE p.vehicle_id = ?
      ORDER BY p.event_time
      ''',
      [vehicleId],
    );
    final points = [
      for (final row in pointRows)
        if (asDouble(row['lat']) != null && asDouble(row['lon']) != null)
          LocationSample(
            packetId: asString(row['packet_id'])!,
            eventTime: requireDateTime(row['event_time']),
            lat: asDouble(row['lat'])!,
            lon: asDouble(row['lon'])!,
            accuracyM: asDouble(row['gps_accuracy']),
          ),
    ];
    final fences = await loadFenceVersions();
    final result = _replay.replay(
      vehicleId: vehicleId,
      points: points,
      fences: fences,
    );

    await db.transaction(() async {
      await db.execute('DELETE FROM geofence_events WHERE vehicle_id = ?', [vehicleId]);
      await db.execute('DELETE FROM trips WHERE vehicle_id = ?', [vehicleId]);
      await db.execute(
        'DELETE FROM vehicle_geofence_current WHERE vehicle_id = ?',
        [vehicleId],
      );
      for (final event in result.events) {
        await db.execute(
          '''
          INSERT INTO geofence_events
            (id, vehicle_id, geofence_id, geofence_version, kind, event_time, packet_id)
          VALUES (?, ?, ?, ?, ?, ?, ?)
          ''',
          [
            event.id,
            event.vehicleId,
            event.geofenceId,
            event.geofenceVersion,
            event.kind,
            event.eventTime,
            event.packetId,
          ],
        );
      }
      for (final trip in result.trips) {
        await db.execute(
          '''
          INSERT INTO trips
            (id, vehicle_id, origin_geofence_id, dest_geofence_id, started_at, ended_at, status)
          VALUES (?, ?, ?, ?, ?, ?, ?)
          ''',
          [
            trip.id,
            trip.vehicleId,
            trip.originGeofenceId,
            trip.destGeofenceId,
            trip.startedAt,
            trip.endedAt,
            trip.status == TripStatus.completed ? 'completed' : 'in_progress',
          ],
        );
      }
      await db.execute(
        'INSERT INTO vehicle_geofence_current (vehicle_id, geofence_id) VALUES (?, ?)',
        [vehicleId, result.currentGeofenceId],
      );
    });
  }

  Future<void> replayAllVehicles() async {
