          : AlertSeverity.warning,
      openedAt: requireDateTime(row['opened_at']),
      resolvedAt: asDateTime(row['resolved_at']),
      dismissedAt: asDateTime(row['dismissed_at']),
      dismissReason: asString(row['dismiss_reason']),
    );
