import 'dart:io';

import 'package:fleet_console/core/clock.dart';
import 'package:fleet_console/data/duckdb/fleet_database.dart';
import 'package:fleet_console/data/fleet_repository.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:path/path.dart' as p;

class RepoHarness {
  RepoHarness._(this.db, this.repo, this.clock, this.dir);

  final FleetDatabase db;
  final FleetRepository repo;
  final FakeClock clock;
  final Directory dir;

  static Future<RepoHarness> open({DateTime? now}) async {
    final dir = await Directory.systemTemp.createTemp('fleet_test_');
    final path = p.join(dir.path, 'fleet.duckdb');
    final db = await FleetDatabase.open(path);
    final clock = FakeClock(now ?? DateTime.utc(2026, 9, 7, 12));
    final repo = FleetRepository(db, clock: clock);
    return RepoHarness._(db, repo, clock, dir);
  }

  Future<void> dispose() async {
    await db.close();
    if (dir.existsSync()) {
      dir.deleteSync(recursive: true);
    }
  }
}

Future<void> withRepo(
  Future<void> Function(RepoHarness h) body, {
  DateTime? now,
}) async {
  final h = await RepoHarness.open(now: now);
  try {
    await body(h);
  } finally {
    await h.dispose();
  }
}

import 'package:fleet_console/core/constants.dart';
import 'package:fleet_console/core/geo.dart';
import 'package:fleet_console/data/engines/geofence_engine.dart';
import 'package:fleet_console/domain/models.dart';
import 'package:flutter_test/flutter_test.dart';

FenceVersion fence({
  required String id,
  required double lat,
  required double lon,
  double radius = 1000,
  DateTime? from,
  DateTime? to,
  int version = 1,
}) {
  return FenceVersion(
    geofenceId: id,
    version: version,
    name: id,
    lat: lat,
    lon: lon,
    radiusM: radius,
    validFrom: from ?? DateTime.utc(2020),
    validTo: to,
  );
}

LocationSample point(
  String id,
  DateTime t,
  double lat,
  double lon, {
  double accuracy = 5,
}) {
  return LocationSample(
    packetId: id,
    eventTime: t,
    lat: lat,
    lon: lon,
    accuracyM: accuracy,
  );
}

void main() {
  final engine = GeofenceReplay();
  final origin = DateTime.utc(2026, 1, 1, 8);
  const depotLat = 13.02;
  const depotLon = 77.59;
  const warehouseLat = 12.97;
  const warehouseLon = 77.68;

  final depot = fence(id: 'depot', lat: depotLat, lon: depotLon);
  final warehouse = fence(id: 'wh', lat: warehouseLat, lon: warehouseLon);

  test('inaccurate GPS is ignored', () {
    final points = [
      for (var i = 0; i < 5; i++)
        point('p$i', origin.add(Duration(seconds: 20 * i)), depotLat, depotLon, accuracy: 80),
    ];
    final result = engine.replay(vehicleId: 'v', points: points, fences: [depot]);
    expect(result.events, isEmpty);
    expect(result.currentGeofenceId, isNull);
  });

  test('jitter inside the hysteresis band does not emit a false exit', () {
    final edge = lerpLatLon(depotLat, depotLon, warehouseLat, warehouseLon, 0.0);
    final points = <LocationSample>[
      for (var i = 0; i < 4; i++)
        point('in$i', origin.add(Duration(seconds: 20 * i)), depotLat, depotLon),
      for (var i = 0; i < 3; i++)
        point(
          'jit$i',
          origin.add(Duration(seconds: 80 + 20 * i)),
          edge.lat + 0.008,
          edge.lon,
        ),
    ];
    final result = engine.replay(vehicleId: 'v', points: points, fences: [depot]);
    expect(result.currentGeofenceId, 'depot');
    expect(result.events.where((e) => e.kind == 'confirmed_exit'), isEmpty);
  });

  test('dwell then a real move starts a trip and a later enter completes it', () {
    final points = <LocationSample>[
      for (var i = 0; i < 4; i++)
        point('d$i', origin.add(Duration(seconds: 30 * i)), depotLat, depotLon),
      for (var i = 1; i <= 6; i++)
        point(
          'c$i',
          origin.add(Duration(seconds: 120 + 30 * i)),
          lerpLatLon(depotLat, depotLon, warehouseLat, warehouseLon, i / 7).lat,
          lerpLatLon(depotLat, depotLon, warehouseLat, warehouseLon, i / 7).lon,
        ),
      for (var i = 0; i < 4; i++)
        point(
          'w$i',
          origin.add(Duration(seconds: 360 + 30 * i)),
          warehouseLat,
          warehouseLon,
        ),
    ];
    final result = engine.replay(
      vehicleId: 'v',
      points: points,
      fences: [depot, warehouse],
    );
    expect(result.events.where((e) => e.kind == 'confirmed_exit').length, 1);
    expect(result.events.where((e) => e.kind == 'confirmed_enter').length, 2);
    expect(result.trips, hasLength(1));
    expect(result.trips.single.status, TripStatus.completed);
    expect(result.trips.single.originGeofenceId, 'depot');
    expect(result.trips.single.destGeofenceId, 'wh');
    expect(result.currentGeofenceId, 'wh');
  });

  test('exit without a later enter leaves the trip in progress', () {
    final points = <LocationSample>[
      for (var i = 0; i < 4; i++)
        point('d$i', origin.add(Duration(seconds: 30 * i)), depotLat, depotLon),
      for (var i = 1; i <= 6; i++)
        point(
          'c$i',
          origin.add(Duration(seconds: 120 + 30 * i)),
          lerpLatLon(depotLat, depotLon, warehouseLat, warehouseLon, i / 7).lat,
          lerpLatLon(depotLat, depotLon, warehouseLat, warehouseLon, i / 7).lon,
        ),
    ];
    final result = engine.replay(
      vehicleId: 'v',
      points: points,
      fences: [depot, warehouse],
    );
    expect(result.trips, hasLength(1));
    expect(result.trips.single.status, TripStatus.inProgress);
  });

  test('replay is idempotent: the same history does not duplicate trips', () {
    final points = <LocationSample>[
      for (var i = 0; i < 4; i++)
        point('d$i', origin.add(Duration(seconds: 30 * i)), depotLat, depotLon),
      for (var i = 1; i <= 6; i++)
        point(
          'c$i',
          origin.add(Duration(seconds: 120 + 30 * i)),
          lerpLatLon(depotLat, depotLon, warehouseLat, warehouseLon, i / 7).lat,
          lerpLatLon(depotLat, depotLon, warehouseLat, warehouseLon, i / 7).lon,
        ),
    ];
    final a = engine.replay(vehicleId: 'v', points: points, fences: [depot, warehouse]);
    final b = engine.replay(vehicleId: 'v', points: points, fences: [depot, warehouse]);
    expect(a.trips.map((t) => t.id), b.trips.map((t) => t.id));
    expect(a.events.map((e) => e.id), b.events.map((e) => e.id));
  });

  test('late extra point can move a trip start without creating a second trip', () {
    final early = <LocationSample>[
      for (var i = 0; i < 4; i++)
        point('d$i', origin.add(Duration(seconds: 30 * i)), depotLat, depotLon),
      for (var i = 1; i <= 6; i++)
        point(
          'c$i',
          origin.add(Duration(seconds: 150 + 30 * i)),
          lerpLatLon(depotLat, depotLon, warehouseLat, warehouseLon, i / 7).lat,
          lerpLatLon(depotLat, depotLon, warehouseLat, warehouseLon, i / 7).lon,
        ),
    ];
    final withLate = [
      ...early,
      point(
        'late',
        origin.add(const Duration(seconds: 130)),
        lerpLatLon(depotLat, depotLon, warehouseLat, warehouseLon, 0.4).lat,
        lerpLatLon(depotLat, depotLon, warehouseLat, warehouseLon, 0.4).lon,
      ),
    ];
    final first = engine.replay(vehicleId: 'v', points: early, fences: [depot, warehouse]);
    final second = engine.replay(vehicleId: 'v', points: withLate, fences: [depot, warehouse]);
    expect(second.trips, hasLength(1));
    expect(first.trips, hasLength(1));
  });

  test('gap longer than 10 minutes does not invent a path', () {
    final points = [
      for (var i = 0; i < 4; i++)
        point('d$i', origin.add(Duration(seconds: 20 * i)), depotLat, depotLon),
      for (var i = 0; i < 4; i++)
        point(
          'w$i',
          origin.add(Duration(minutes: 20 + i)),
          warehouseLat,
          warehouseLon,
        ),
    ];
    final result = engine.replay(
      vehicleId: 'v',
      points: points,
      fences: [depot, warehouse],
    );
    expect(result.currentGeofenceId, 'wh');
    expect(result.trips.where((t) => t.status == TripStatus.completed), isEmpty);
  });

  test('innermost overlapping fence wins', () {
    final outer = fence(id: 'outer', lat: depotLat, lon: depotLon, radius: 3000);
    final inner = fence(id: 'inner', lat: depotLat, lon: depotLon, radius: 800);
    final points = [
      for (var i = 0; i < 4; i++)
        point('p$i', origin.add(Duration(seconds: 20 * i)), depotLat, depotLon),
    ];
    final result = engine.replay(
      vehicleId: 'v',
      points: points,
      fences: [outer, inner],
    );
    expect(result.currentGeofenceId, 'inner');
  });

  test('geofence version valid_to hides the fence for later points', () {
    final cut = origin.add(const Duration(minutes: 5));
    final versioned = fence(
      id: 'depot',
      lat: depotLat,
      lon: depotLon,
      to: cut,
    );
    final points = [
      for (var i = 0; i < 4; i++)
        point('early$i', origin.add(Duration(seconds: 20 * i)), depotLat, depotLon),
      for (var i = 0; i < 4; i++)
        point('late$i', cut.add(Duration(seconds: 20 * i)), depotLat, depotLon),
    ];
    final result = engine.replay(vehicleId: 'v', points: points, fences: [versioned]);
    expect(result.currentGeofenceId, isNull);
  });

  test('returning to the origin geofence is a valid completed trip', () {
    final points = <LocationSample>[
      for (var i = 0; i < 4; i++)
        point('a$i', origin.add(Duration(seconds: 20 * i)), depotLat, depotLon),
      for (var i = 1; i <= 5; i++)
        point(
          'mid$i',
          origin.add(Duration(seconds: 80 + 20 * i)),
          lerpLatLon(depotLat, depotLon, warehouseLat, warehouseLon, 0.5).lat,
          lerpLatLon(depotLat, depotLon, warehouseLat, warehouseLon, 0.5).lon,
        ),
      for (var i = 0; i < 4; i++)
        point(
          'b$i',
          origin.add(Duration(seconds: 220 + 20 * i)),
          depotLat,
          depotLon,
        ),
    ];
    final result = engine.replay(vehicleId: 'v', points: points, fences: [depot]);
    expect(result.trips, hasLength(1));
    expect(result.trips.single.originGeofenceId, 'depot');
    expect(result.trips.single.destGeofenceId, 'depot');
    expect(result.trips.single.status, TripStatus.completed);
  });
}

import 'package:fleet_console/core/constants.dart';
import 'package:fleet_console/data/engines/alert_engine.dart';
import 'package:fleet_console/domain/models.dart';
import 'package:flutter_test/flutter_test.dart';

void main() {
  final now = DateTime.utc(2026, 9, 7, 12);

  test('SOC below 20% is warning and below 10% is critical on one kind', () {
    final warn = AlertRules.evaluate(now: now, latest: {
      FleetRules.signalSoc: (value: 15, eventTime: now),
    });
    final crit = AlertRules.evaluate(now: now, latest: {
      FleetRules.signalSoc: (value: 8, eventTime: now),
    });
    expect(warn.where((e) => e.kind == FleetRules.alertSoc && e.inBreach), hasLength(1));
    expect(warn.firstWhere((e) => e.kind == FleetRules.alertSoc).severity, AlertSeverity.warning);
    expect(crit.firstWhere((e) => e.kind == FleetRules.alertSoc).severity, AlertSeverity.critical);
  });

  test('stale SOC cannot open an alert', () {
    final eval = AlertRules.evaluate(now: now, latest: {
      FleetRules.signalSoc: (
        value: 5,
        eventTime: now.subtract(const Duration(minutes: 11)),
      ),
    });
    final soc = eval.firstWhere((e) => e.kind == FleetRules.alertSoc);
    expect(soc.inBreach, isFalse);
    expect(soc.fresh, isFalse);
  });

  test('overheat is a separate critical alert', () {
    final eval = AlertRules.evaluate(now: now, latest: {
      FleetRules.signalSoc: (value: 80, eventTime: now),
      FleetRules.signalBatteryTemp: (value: 46, eventTime: now),
    });
    expect(eval.firstWhere((e) => e.kind == FleetRules.alertSoc).inBreach, isFalse);
    expect(eval.firstWhere((e) => e.kind == FleetRules.alertTemp).inBreach, isTrue);
    expect(eval.firstWhere((e) => e.kind == FleetRules.alertTemp).severity, AlertSeverity.critical);
  });

  test('register verdict is STALE when older than 10 minutes', () {
    expect(
      verdictFor(
        now: now,
        signal: FleetRules.signalSoc,
        value: 50,
        eventTime: now.subtract(const Duration(minutes: 11)),
      ),
      SignalVerdict.stale,
    );
  });

  test('never-reported signals have no verdict', () {
    expect(
      verdictFor(
        now: now,
        signal: FleetRules.signalRange,
        value: 12,
        eventTime: now,
      ),
      SignalVerdict.normal,
    );
  });
}

import 'package:fleet_console/core/constants.dart';
import 'package:fleet_console/domain/models.dart';
import 'package:flutter_test/flutter_test.dart';

import 'helpers/harness.dart';

TelemetryPacket pkt(
  String vehicle,
  DateTime t,
  Map<String, double> signals, {
  String? id,
}) {
  return TelemetryPacket(
    id: id ?? 'pkt_${vehicle}_${t.microsecondsSinceEpoch}',
    vehicleId: vehicle,
    eventTime: t,
    signals: signals,
  );
}

void main() {
  test('duplicate packets are ignored', () async {
    await withRepo((h) async {
      await h.repo.upsertVehicle(id: 'v1', regNumber: 'KA01', model: 'Semi');
      final t = h.clock.now().subtract(const Duration(minutes: 1));
      final packet = pkt('v1', t, {FleetRules.signalSoc: 50, FleetRules.signalSpeed: 10});
      expect((await h.repo.ingestPacket(packet)).accepted, isTrue);
      expect((await h.repo.ingestPacket(packet)).duplicate, isTrue);
      final stats = await h.repo.stats();
      expect(stats.packets, 1);
    });
  });

  test('late packet older than current latest does not clobber SOC', () async {
    await withRepo((h) async {
      await h.repo.upsertVehicle(id: 'v1', regNumber: 'KA01', model: 'Semi');
      final now = h.clock.now();
      await h.repo.ingestPacket(
        pkt('v1', now.subtract(const Duration(minutes: 1)), {FleetRules.signalSoc: 80}),
      );
      await h.repo.ingestPacket(
        pkt('v1', now.subtract(const Duration(minutes: 4)), {FleetRules.signalSoc: 10}),
      );
      final register = await h.repo.loadRegister('v1');
      final soc = register.firstWhere((r) => r.signal == FleetRules.signalSoc);
      expect(soc.value, 80);
    });
  });

  test('status first-match-wins including missing speed/ignition', () async {
    await withRepo((h) async {
      Future<VehicleRow> one(String id, Map<String, double> signals, {Duration ago = const Duration(minutes: 1)}) async {
        await h.repo.upsertVehicle(id: id, regNumber: id, model: 'M');
        await h.repo.ingestPacket(pkt(id, h.clock.now().subtract(ago), signals));
        return (await h.repo.loadVehicle(id))!;
      }

      final moving = await one('moving', {FleetRules.signalSpeed: 12, FleetRules.signalIgnition: 0});
      final idle = await one('idle', {FleetRules.signalSpeed: 0, FleetRules.signalIgnition: 1});
      final stopped = await one('stopped', {FleetRules.signalIgnition: 0});
      final missing = await one('missing', {FleetRules.signalSoc: 40});
      final offline = await one(
        'offline',
        {FleetRules.signalSpeed: 30},
        ago: const Duration(minutes: 11),
      );

      expect(moving.status, VehicleStatus.moving);
      expect(idle.status, VehicleStatus.idle);
      expect(stopped.status, VehicleStatus.stopped);
      expect(missing.status, VehicleStatus.stopped);
      expect(offline.status, VehicleStatus.offline);
    });
  });

  test('filter counts come from SQL', () async {
    await withRepo((h) async {
      await h.repo.upsertVehicle(id: 'a', regNumber: 'A', model: 'M');
      await h.repo.upsertVehicle(id: 'b', regNumber: 'B', model: 'M');
      await h.repo.ingestPacket(
        pkt('a', h.clock.now().subtract(const Duration(minutes: 1)), {FleetRules.signalSpeed: 5}),
      );
      await h.repo.ingestPacket(
        pkt('b', h.clock.now().subtract(const Duration(minutes: 12)), {FleetRules.signalSpeed: 5}),
      );
      final snap = await h.repo.loadFleet();
      expect(snap.counts.all, 2);
      expect(snap.counts.moving, 1);
      expect(snap.counts.offline, 1);
      final onlyOffline = await h.repo.loadFleet(filter: FleetFilter.offline);
      expect(onlyOffline.vehicles, hasLength(1));
      expect(onlyOffline.vehicles.single.id, 'b');
    });
  });

  test('SOC escalation is one alert row and dismiss+undo works', () async {
    await withRepo((h) async {
      await h.repo.upsertVehicle(id: 'v1', regNumber: 'KA01', model: 'Semi');
      final t = h.clock.now().subtract(const Duration(minutes: 1));
      await h.repo.ingestPacket(pkt('v1', t, {FleetRules.signalSoc: 15}));
      var alerts = await h.repo.loadOpenAlerts(vehicleId: 'v1');
      expect(alerts, hasLength(1));
      expect(alerts.single.severity, AlertSeverity.warning);

      await h.repo.ingestPacket(
        pkt('v1', t.add(const Duration(seconds: 10)), {FleetRules.signalSoc: 8}),
      );
      alerts = await h.repo.loadOpenAlerts(vehicleId: 'v1');
      expect(alerts, hasLength(1));
      expect(alerts.single.severity, AlertSeverity.critical);

      final id = alerts.single.id;
      await h.repo.dismissAlert(alertId: id, reason: 'I am on it');
      expect(await h.repo.loadOpenAlerts(vehicleId: 'v1'), isEmpty);
      await h.repo.undoDismiss(id);
      expect(await h.repo.loadOpenAlerts(vehicleId: 'v1'), hasLength(1));
    });
  });

  test('clearing SOC resolves even a dismissed alert', () async {
    await withRepo((h) async {
      await h.repo.upsertVehicle(id: 'v1', regNumber: 'KA01', model: 'Semi');
      final t = h.clock.now().subtract(const Duration(minutes: 1));
      await h.repo.ingestPacket(pkt('v1', t, {FleetRules.signalSoc: 12}));
      final id = (await h.repo.loadOpenAlerts(vehicleId: 'v1')).single.id;
      await h.repo.dismissAlert(alertId: id, reason: 'Wrong alert');
      await h.repo.ingestPacket(
        pkt('v1', t.add(const Duration(seconds: 20)), {FleetRules.signalSoc: 40}),
      );
      final rows = await h.db.select('SELECT resolved_at FROM alerts WHERE id = ?', [id]);
      expect(rows.single['resolved_at'], isNotNull);
    });
  });

  test('kill-and-relaunch reads the same vehicles from the file', () async {
    final h = await RepoHarness.open();
    final path = h.db.path;
    try {
      await h.repo.upsertVehicle(id: 'v1', regNumber: 'KA99ZZ', model: 'Semi');
      await h.repo.ingestPacket(
        pkt('v1', h.clock.now(), {FleetRules.signalSoc: 66, FleetRules.signalSpeed: 3}),
      );
      await h.db.close();
      final db2 = await FleetDatabase.open(path);
      final repo2 = FleetRepository(db2, clock: h.clock);
      final snap = await repo2.loadFleet();
      expect(snap.vehicles, hasLength(1));
      expect(snap.vehicles.single.regNumber, 'KA99ZZ');
      expect(snap.vehicles.single.soc, 66);
      await db2.close();
    } finally {
      await h.dispose();
    }
  });

  test('never-reported signals show as null with no pill', () async {
    await withRepo((h) async {
      await h.repo.upsertVehicle(id: 'v1', regNumber: 'KA01', model: 'Semi');
      await h.repo.ingestPacket(pkt('v1', h.clock.now(), {FleetRules.signalSoc: 50}));
      final register = await h.repo.loadRegister('v1');
      final range = register.firstWhere((r) => r.signal == FleetRules.signalRange);
      expect(range.value, isNull);
      expect(range.verdict, isNull);
    });
  });
}

